// A real referrer is permanent. Share its first successful read across panels,
// chain snapshots and page loads; never freeze an unassigned/Vault fallback.
import { CHAIN, CONTRACTS } from './chain-config.js';

const memory = new Map();
const flights = new Map();
const lower = value => String(value || '').toLowerCase();
const isAddress = value => /^0x[0-9a-f]{40}$/.test(value);
const ZERO_ADDRESS = '0x0000000000000000000000000000000000000000';

function keyFor(player, { chain = CHAIN, contracts = CONTRACTS } = {}) {
  const address = lower(player);
  if (!isAddress(address)) return null;
  return `degenerus:referrer:v1:${chain.id}:${chain.deployBlock ?? 0}:${contracts.GAME}:${contracts.AFFILIATE}:${address}`.toLowerCase();
}

function realReferrer(value, { contracts = CONTRACTS } = {}) {
  const address = lower(value);
  return isAddress(address) && address !== ZERO_ADDRESS && address !== lower(contracts.VAULT)
    ? address : null;
}

export function cachedPlayerReferrer(player, scope) {
  const key = keyFor(player, scope);
  if (!key) return null;
  if (memory.has(key)) return memory.get(key);
  try {
    const saved = realReferrer(localStorage.getItem(key), scope);
    if (saved) { memory.set(key, saved); return saved; }
  } catch (_) { /* Memory caching still works without browser storage. */ }
  return null;
}

export function rememberPlayerReferrer(player, value, scope) {
  const saved = cachedPlayerReferrer(player, scope);
  if (saved) return saved;
  const key = keyFor(player, scope), referrer = realReferrer(value, scope);
  if (!key || !referrer) return null;
  memory.set(key, referrer);
  try { localStorage.setItem(key, referrer); } catch (_) { /* Memory remains available. */ }
  return referrer;
}

export async function loadPlayerReferrer(player, read, scope) {
  const saved = cachedPlayerReferrer(player, scope);
  if (saved) return saved;
  const key = keyFor(player, scope);
  if (!key) return null;
  if (!flights.has(key)) {
    const flight = Promise.resolve().then(read).then(value =>
      rememberPlayerReferrer(player, value, scope) ?? value
    ).finally(() => { if (flights.get(key) === flight) flights.delete(key); });
    flights.set(key, flight);
  }
  return flights.get(key);
}

/** Test seam: emulate a page reload without discarding persistent entries. */
export function resetReferrerCacheForTest() { memory.clear(); flights.clear(); }
